import json,sys
d=json.load(sys.stdin)
def walk(items):
    for it in items:
        ch=it.get('children') or []
        if ch:
            st=[c.get('status') for c in ch]
            done=sum(1 for s in st if s in ('done','rejected'))
            if done==len(st) and it.get('status') not in ('done','rejected'):
                print('ALL-CHILDREN-DONE but parent', it.get('status'),':', it['id'], st)
            if it.get('status')=='done' and any(s not in ('done','rejected') for s in st):
                print('DONE parent with open children:', it['id'], [(c['id'],c['status']) for c in ch if c['status'] not in ('done','rejected')])
            if it.get('status')=='pending' and any(s in ('done','active') for s in st):
                print('PENDING parent with progress:', it['id'], done,'/',len(st))
        walk(ch)
walk(d.get('items') or [])
"

