import json,sys,collections
d=json.load(sys.stdin)
items=d.get('items') or []
print('keys of first item:', list(items[0].keys()))
byid={i['id']:i for i in items}
kids=collections.defaultdict(list)
for i in items:
    p=i.get('parent')
    if p: kids[p].append(i)
term={'done','rejected','cancelled'}
for i in items:
    ch=kids.get(i['id'])
    if not ch: continue
    st=[c.get('status') for c in ch]
    open_ch=[(c['id'],c['status']) for c in ch if c['status'] not in term]
    if not open_ch and i['status'] not in term:
        print('[A] all children terminal, parent', i['status'], '->', i['id'], st)
    if i['status'] in ('done',) and open_ch:
        print('[B] done parent, open children ->', i['id'], open_ch[:6])
    if i['status']=='pending' and any(s=='done' for s in st):
        print('[C] pending parent with', sum(1 for s in st if s=='done'),'/',len(st),'done ->', i['id'])
    if i['status']=='blocked' and all(s in term for s in st) and st:
        print('[D] blocked parent, all children terminal ->', i['id'])
"

